Function siguiente <- MasUno(x As Integer)
  Define siguiente As Integer;
  siguiente <- x + 1;
EndFunction

Function doble <- Doble(x As Integer)
  Define doble As Integer;
  doble <- x * 2;
EndFunction

Function compuesta <- Componer(f As Function(Integer) As Integer, g As Function(Integer) As Integer)
  Define compuesta As Function(Integer) As Integer <- Function(x As Integer) As Integer
    Return f(g(x));
  EndFunction;
EndFunction

Algorithm Componer
  Define x As Integer;
  Read x;
  Define dobleMasUno As Function(Integer) As Integer <- Componer(MasUno, Doble);
  Define dobleDelSiguiente As Function(Integer) As Integer <- Componer(Doble, MasUno);
  Write dobleMasUno(x);
  Write dobleDelSiguiente(x);
EndAlgorithm
